sys_script_include.script:
var PatientService = Class.create();

PatientService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Patient record exists.
     *
     * @param {String} patientSysId
     * @return {Boolean}
     */
    patientExists: function(patientSysId) {

        if (this.validationUtils.isEmpty(patientSysId)) {
            return false;
        }

        var patient = new GlideRecord('x_2130921_caresy_0_patient');

        if (!patient.isValid()) {
            gs.error('PatientService: Patient table is invalid.');
            return false;
        }

        return patient.get(patientSysId);
    },

    /**
     * Retrieve a Patient record.
     *
     * @param {String} patientSysId
     * @return {GlideRecord|null}
     */
    getPatient: function(patientSysId) {

        if (this.validationUtils.isEmpty(patientSysId)) {
            return null;
        }

        var patient = new GlideRecord('x_2130921_caresy_0_patient');

        if (!patient.isValid()) {
            gs.error('PatientService: Patient table is invalid.');
            return null;
        }

        if (patient.get(patientSysId)) {
            return patient;
        }

        return null;
    },

    /**
     * Check whether a Patient is active.
     *
     * @param {String} patientSysId
     * @return {Boolean}
     */
    isPatientActive: function(patientSysId) {

        var patient = this.getPatient(patientSysId);

        if (!patient) {
            return false;
        }

        return patient.getValue('active') == 'true';
    },

    type: 'PatientService'
};
